<section class="panel data-panel"><div class="panel-heading"><div><h2>Daftar kelas <span class="count-badge"><?= count($rows) ?></span></h2><p>Semua data kelas</p></div><form class="search-form" method="get"><span>⌕</span><input name="q" value="<?= e($q) ?>" placeholder="Cari data..."><button type="submit">Cari</button></form></div><div class="table-wrap"><table><thead><tr><th>Nama kelas</th><th>Tingkat</th><th>Aksi</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="3" class="empty-cell"><div class="empty-icon">⌕</div><b>Belum ada data</b><p>Tambahkan data kelas pertama.</p></td></tr><?php else: foreach($rows as $r): ?><tr><td><?= e($r['nama_kelas']) ?></td><td><?= e($r['tingkat']) ?></td><td><div class="row-actions"><a class="action-edit" href="edit.php?id=<?= (int)$r['id'] ?>">Edit</a><form method="post" action="hapus.php" onsubmit="return confirm('Hapus data ini? Tindakan ini tidak bisa dibatalkan.');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="action-delete" type="submit">Hapus</button></form></div></td></tr><?php endforeach; endif; ?></tbody></table></div><div class="table-footer">Menampilkan <b><?= count($rows) ?></b> data kelas <span>Terakhir diperbarui: <?= date('d M Y') ?></span></div></section><?php require __DIR__.'/../includes/footer.php'; ?>